<?php
defined('ABSPATH') || exit;

/** Student endpoints deliberately separate options from keys; every personal predicate includes user_id. */
final class CAFCC_MCQ_Student {
    public static function filters($v){
        $out=array();foreach(array('subject','attempt','source','series','search','standard','concept','mode') as $k){$s=$v[$k]??'';if(!is_string($s)||strlen($s)>190)return CAFCC_Repository::error('Invalid MCQ filter.');$out[$k]=sanitize_text_field($s);}if($out['subject']&&!in_array($out['subject'],array('FR','AFM','AUDIT','DT','IDT','IBS'),true))return CAFCC_Repository::error('Unknown subject.');if($out['source']&&!in_array($out['source'],array('rtp','mtp','exam','other'),true))return CAFCC_Repository::error('Unknown source.');if($out['standard']&&!CAFCC_Standards::entry($out['standard']))return CAFCC_Repository::error('Choose a supported standard.');if(!in_array($out['mode'],array('','all','unattempted','incorrect','bookmarked','attempted'),true))return CAFCC_Repository::error('Unknown MCQ practice mode.');$out['page']=max(1,min(100000,(int)($v['page']??1)));return $out;
    }
    public static function parts($f){
        global $wpdb;$uid=get_current_user_id();$where=CAFCC_MCQ::guard('m');$a=array();foreach(array('subject'=>'subject_code','attempt'=>'exam_attempt','source'=>'source_type','series'=>'mtp_series') as $k=>$col)if($f[$k]!==''){$where.=" AND m.$col=%s";$a[]=$f[$k];}$tags=CAFCC_MCQ::table('tags');
        foreach(array('standard','concept') as $k)if($f[$k]!==''){$where.=" AND EXISTS(SELECT 1 FROM $tags ft WHERE ft.mcq_id=m.id AND ".($k==='standard'?CAFCC_Search_Tags::predicate('ft',$f[$k],$a):'ft.normalised=%s').')';if($k==='concept')$a[]=CAFCC_Search_Tags::normalise(preg_replace('/^tag:/','',$f[$k]));}
        if($f['search']!==''){$n=CAFCC_Search_Tags::normalise($f['search']);$tagArgs=array();$pred=CAFCC_Search_Tags::predicate('st',$f['search'],$tagArgs);$where.=' AND (';if(!CAFCC_Search_Tags::standard_query($f['search'])){$where.='m.search_text LIKE %s OR ';$a[]='%'.$wpdb->esc_like($n).'%';}$where.="EXISTS(SELECT 1 FROM $tags st WHERE st.mcq_id=m.id AND $pred))";array_push($a,...$tagArgs);}
        $at=CAFCC_MCQ::table('attempts');if(in_array($f['mode'],array('unattempted','attempted'),true)){$where.=($f['mode']==='unattempted'?' AND NOT':' AND')." EXISTS(SELECT 1 FROM $at at WHERE at.mcq_id=m.id AND at.user_id=%d)";$a[]=$uid;}elseif($f['mode']==='incorrect'){$where.=" AND (SELECT at.is_correct FROM $at at WHERE at.mcq_id=m.id AND at.user_id=%d ORDER BY at.id DESC LIMIT 1)=0";$a[]=$uid;}elseif($f['mode']==='bookmarked'){$where.=' AND EXISTS(SELECT 1 FROM '.CAFCC_MCQ::table('personal').' p WHERE p.mcq_id=m.id AND p.user_id=%d AND p.bookmark=1)';$a[]=$uid;}return array('FROM '.CAFCC_MCQ::table('questions').' m',$where,$a);
    }
    public static function list($v){if(is_wp_error($e=CAFCC_Library::allowed()))return $e;$f=self::filters($v);if(is_wp_error($f))return $f;global $wpdb;[$from,$w,$a]=self::parts($f);$count=(int)$wpdb->get_var($a?$wpdb->prepare("SELECT COUNT(*) $from WHERE $w",$a):"SELECT COUNT(*) $from WHERE $w");$sql="SELECT m.id,m.stable_id,m.occurrence_key,m.subject_code,m.source_type,m.exam_attempt,m.mtp_series,m.question_number,m.revision $from WHERE $w ORDER BY m.id LIMIT 20 OFFSET ".(($f['page']-1)*20);$rows=$wpdb->get_results($a?$wpdb->prepare($sql,$a):$sql,ARRAY_A);foreach($rows as &$r)$r['tags']=CAFCC_MCQ::tags($r['id']);return array('items'=>$rows,'total'=>$count,'page'=>$f['page'],'per_page'=>20);}
    public static function facets($v){if(is_wp_error($e=CAFCC_Library::allowed()))return $e;$f=self::filters($v);if(is_wp_error($f))return $f;global $wpdb;$selected_standard=$f['standard'];$f['standard']='';$f['concept']='';$f['search']='';[$from,$w,$a]=self::parts($f);$tags=$wpdb->get_results(($a?$wpdb->prepare("SELECT t.label,t.normalised,t.kind,COUNT(DISTINCT m.id) AS questions $from JOIN ".CAFCC_MCQ::table('tags')." t ON t.mcq_id=m.id WHERE $w GROUP BY t.label,t.normalised,t.kind ORDER BY questions DESC,t.label LIMIT 200",$a):"SELECT t.label,t.normalised,t.kind,COUNT(DISTINCT m.id) AS questions $from JOIN ".CAFCC_MCQ::table('tags')." t ON t.mcq_id=m.id WHERE $w GROUP BY t.label,t.normalised,t.kind ORDER BY questions DESC,t.label LIMIT 200"),ARRAY_A);$standards=array();$concepts=array();foreach($tags as $t){$entry=CAFCC_Standards::entry($t['label']);if($entry)$standards[$entry['code']]=array('id'=>$entry['code'],'label'=>$entry['code'].' — '.$entry['title'],'questions'=>(int)$t['questions']);elseif(in_array($t['kind'],array('concept','owner_tag'),true))$concepts[]=array('id'=>$t['normalised'],'label'=>$t['label'],'questions'=>(int)$t['questions']);}if($selected_standard){$cf=$f;$cf['standard']=$selected_standard;[$cfrom,$cw,$ca]=self::parts($cf);$cs="SELECT t.label,t.normalised,COUNT(DISTINCT m.id) AS questions $cfrom JOIN ".CAFCC_MCQ::table('tags')." t ON t.mcq_id=m.id AND t.kind IN ('concept','owner_tag') WHERE $cw GROUP BY t.label,t.normalised ORDER BY questions DESC,t.label LIMIT 100";$cr=$wpdb->get_results($ca?$wpdb->prepare($cs,$ca):$cs,ARRAY_A);$concepts=array();foreach($cr as $c)if(!CAFCC_Standards::entry($c['label']))$concepts[]=array('id'=>$c['normalised'],'label'=>$c['label'],'questions'=>(int)$c['questions']);}$attempts=$wpdb->get_col('SELECT DISTINCT exam_attempt FROM '.CAFCC_MCQ::table('questions').' m WHERE '.CAFCC_MCQ::guard().' ORDER BY exam_attempt');return array('standards'=>array_values($standards),'concepts'=>$concepts,'attempts'=>$attempts);}
    public static function open($id){if(is_wp_error($e=CAFCC_Library::allowed()))return $e;$r=CAFCC_MCQ::get($id);if(!CAFCC_MCQ::visible($r))return CAFCC_Repository::error('This MCQ is not available for practice.',404);return $r;}
    public static function question($id){$r=self::open($id);if(is_wp_error($r))return $r;global $wpdb;$uid=get_current_user_id();$p=$wpdb->get_row($wpdb->prepare('SELECT bookmark,tags FROM '.CAFCC_MCQ::table('personal').' WHERE user_id=%d AND mcq_id=%d',$uid,$id),ARRAY_A);$scenario=$r['scenario_id']?$wpdb->get_var($wpdb->prepare('SELECT body_html FROM '.CAFCC_MCQ::table('scenarios').' WHERE id=%d',$r['scenario_id'])):'';$history=$wpdb->get_results($wpdb->prepare('SELECT attempt_number,is_correct,active_seconds,created_at FROM '.CAFCC_MCQ::table('attempts').' WHERE user_id=%d AND mcq_id=%d ORDER BY id DESC LIMIT 20',$uid,$id),ARRAY_A);return array('id'=>(int)$id,'stable_id'=>$r['stable_id'],'occurrence_key'=>$r['occurrence_key'],'revision'=>(int)$r['revision'],'subject'=>$r['subject_code'],'source'=>$r['source_type'],'attempt'=>$r['exam_attempt'],'series'=>$r['mtp_series'],'reference'=>$r['question_number'],'question_html'=>$r['question_html'],'common_facts_html'=>$scenario,'options'=>array_map(function($o){return array('id'=>$o['id'],'html'=>$o['html']);},$r['options']),'multiple_selection'=>$r['key_policy']==='all_of','citation'=>CAFCC_MCQ::citation($r),'tags'=>CAFCC_MCQ::tags($id),'personal'=>array('bookmark'=>(bool)($p['bookmark']??false),'tags'=>json_decode($p['tags']??'[]',true)),'history'=>$history);}
    public static function lock_personal($id){global $wpdb;$uid=get_current_user_id();$t=CAFCC_MCQ::table('personal');if(false===$wpdb->query($wpdb->prepare("INSERT IGNORE INTO $t (user_id,mcq_id,tags,updated_at) VALUES (%d,%d,'[]',%s)",$uid,$id,current_time('mysql',true))))return CAFCC_Repository::error('Cannot retain private MCQ activity.',500);return $wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE user_id=%d AND mcq_id=%d FOR UPDATE",$uid,$id),ARRAY_A);}
    public static function begin($id){return CAFCC_Academic::transaction(function()use($id){$r=self::open($id);if(is_wp_error($r))return $r;global $wpdb;$p=self::lock_personal($id);if(is_wp_error($p))return $p;$uid=get_current_user_id();$t=CAFCC_MCQ::table('sessions');$s=$wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE user_id=%d AND mcq_id=%d AND status='open' AND content_revision=%d ORDER BY id DESC LIMIT 1 FOR UPDATE",$uid,$id,$r['revision']),ARRAY_A);if(!$s){$s=array('session_key'=>wp_generate_uuid4(),'user_id'=>$uid,'mcq_id'=>$id,'content_revision'=>$r['revision'],'started_at'=>current_time('mysql',true),'selection_json'=>'[]');if(false===$wpdb->insert($t,$s))return CAFCC_Repository::error('Cannot start MCQ session.',500);}return array('session_key'=>$s['session_key'],'started_at'=>$s['started_at'],'server_time'=>current_time('mysql',true));});}
    public static function choice($r,$selected){if(!is_array($selected)||!array_is_list($selected)||!$selected||count($selected)>10)return CAFCC_Repository::error('Select an answer before checking.');foreach($selected as $s)if(!is_string($s)||!in_array($s,array_column($r['options'],'id'),true))return CAFCC_Repository::error('Selected option is not in this question.');$selected=array_values(array_unique($selected));sort($selected);if($r['key_policy']!=='all_of'&&count($selected)!==1)return CAFCC_Repository::error('Select one option.');return $selected;}
    public static function matches($r,$selected){return $r['key_policy']==='any_of'?(bool)array_intersect($r['correct'],$selected):$selected===$r['correct'];}
    public static function record($r,$selected,$seconds,$test=0){global $wpdb;$p=self::lock_personal($r['id']);if(is_wp_error($p))return $p;$uid=get_current_user_id();$t=CAFCC_MCQ::table('attempts');$number=(int)$wpdb->get_var($wpdb->prepare("SELECT MAX(attempt_number) FROM $t WHERE user_id=%d AND mcq_id=%d",$uid,$r['id']))+1;$row=array('user_id'=>$uid,'mcq_id'=>$r['id'],'occurrence_key'=>$r['occurrence_key'],'attempt_number'=>$number,'selection_json'=>wp_json_encode($selected),'is_correct'=>self::matches($r,$selected)?1:0,'active_seconds'=>max(0,min(86400,(int)$seconds)),'content_revision'=>$r['revision'],'key_fingerprint'=>CAFCC_MCQ::fingerprint($r),'test_id'=>$test,'created_at'=>current_time('mysql',true));if(false===$wpdb->insert($t,$row))return CAFCC_Repository::error('Cannot retain the scored MCQ attempt.',500);$row['id']=$wpdb->insert_id;return $row;}
    public static function feedback($r,$attempt){return array('attempt_id'=>(int)$attempt['id'],'attempt_number'=>(int)$attempt['attempt_number'],'selected'=>json_decode($attempt['selection_json'],true),'is_correct'=>(bool)$attempt['is_correct'],'correct_options'=>$r['correct'],'selection_policy'=>$r['key_policy'],'seconds'=>(int)$attempt['active_seconds'],'explanation_html'=>CAFCC_Practice::html($r['data']['explanation_html']??''),'answer_page'=>(int)$r['data']['answer']['page'],'answer_url'=>(CAFCC_Public_Sources::find($r['data']['answer']['source_hash'],'answer')['url']??$r['data']['answer']['official_url']),'attribution'=>'ICAI source acknowledgment · printed answer key; provisional owner publication');}
    public static function check($id,$v){if(!is_array($v)||array_diff(array_keys($v),array('session_key','selected')))return CAFCC_Repository::error('Invalid MCQ answer request.');return CAFCC_Academic::transaction(function()use($id,$v){global $wpdb;$r=self::open($id);if(is_wp_error($r))return $r;$selected=self::choice($r,$v['selected']??null);if(is_wp_error($selected))return $selected;$p=self::lock_personal($id);if(is_wp_error($p))return $p;$s=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.CAFCC_MCQ::table('sessions').' WHERE session_key=%s AND user_id=%d AND mcq_id=%d FOR UPDATE',is_string($v['session_key']??null)?$v['session_key']:'',get_current_user_id(),$id),ARRAY_A);if(!$s||(int)$s['content_revision']!==(int)$r['revision'])return CAFCC_Repository::error('MCQ session is unavailable or content changed. Reopen the question.',409);if($s['status']==='checked'){if($s['selection_json']!==wp_json_encode($selected))return CAFCC_Repository::error('This session was already scored. Use Reattempt.',409);$attempt=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.CAFCC_MCQ::table('attempts').' WHERE id=%d AND user_id=%d',$s['attempt_id'],get_current_user_id()),ARRAY_A);return self::feedback($r,$attempt);}$seconds=max(0,time()-strtotime($s['started_at'].' UTC'));$attempt=self::record($r,$selected,$seconds);if(is_wp_error($attempt))return $attempt;if(false===$wpdb->update(CAFCC_MCQ::table('sessions'),array('status'=>'checked','selection_json'=>wp_json_encode($selected),'attempt_id'=>$attempt['id']),array('id'=>$s['id'])))return CAFCC_Repository::error('Cannot retain MCQ answer checkpoint.',500);return self::feedback($r,$attempt);});}
    public static function personal($id,$v){if(!is_array($v)||array_diff(array_keys($v),array('bookmark','tags')))return CAFCC_Repository::error('Only your MCQ bookmark/tags may be changed.');if(isset($v['bookmark'])&&!is_bool($v['bookmark']))return CAFCC_Repository::error('Use a boolean bookmark.');$tags=$v['tags']??null;if($tags!==null){if(!is_array($tags)||!array_is_list($tags)||count($tags)>20)return CAFCC_Repository::error('Use up to twenty private tags.');foreach($tags as &$t){if(!is_string($t)||strlen($t)>80)return CAFCC_Repository::error('Use short private tags.');$t=sanitize_text_field($t);}unset($t);}return CAFCC_Academic::transaction(function()use($id,$v,$tags){$r=self::open($id);if(is_wp_error($r))return $r;global $wpdb;$p=self::lock_personal($id);if(is_wp_error($p))return $p;$row=array('bookmark'=>isset($v['bookmark'])?($v['bookmark']?1:0):$p['bookmark'],'tags'=>$tags===null?$p['tags']:wp_json_encode(array_values(array_unique($tags))),'updated_at'=>current_time('mysql',true));if(false===$wpdb->update(CAFCC_MCQ::table('personal'),$row,array('user_id'=>get_current_user_id(),'mcq_id'=>$id)))return CAFCC_Repository::error('Cannot save private MCQ activity.',500);return array('saved'=>true);});}
    public static function activity($v){
        if(is_wp_error($e=CAFCC_Library::allowed()))return $e;$outcome=$v['outcome']??'all';if(!is_string($outcome)||!in_array($outcome,array('all','correct','incorrect'),true))return CAFCC_Repository::error('Choose a scored result.');$page=max(1,min(100000,(int)($v['page']??1)));global $wpdb;$uid=get_current_user_id();$t=CAFCC_MCQ::table('attempts');$q=CAFCC_MCQ::table('questions');$w='at.user_id=%d';$a=array($uid);if($outcome!=='all'){$w.=' AND at.is_correct=%d';$a[]=$outcome==='correct'?1:0;}$total=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $t at WHERE $w",$a));$rows=$wpdb->get_results($wpdb->prepare("SELECT at.attempt_number,at.is_correct,at.active_seconds,at.created_at,m.id,m.stable_id,m.subject_code,m.source_type,m.exam_attempt,m.mtp_series,m.question_number FROM $t at JOIN $q m ON m.id=at.mcq_id WHERE $w ORDER BY at.id DESC LIMIT 20 OFFSET ".(($page-1)*20),$a),ARRAY_A);return array('items'=>$rows,'total'=>$total,'page'=>$page,'per_page'=>20,'outcome'=>$outcome);
    }
    public static function metrics(){global $wpdb;$uid=get_current_user_id();$t=CAFCC_MCQ::table('attempts');$q=CAFCC_MCQ::table('questions');$a=$wpdb->get_row($wpdb->prepare("SELECT COUNT(*) AS attempts,COUNT(DISTINCT mcq_id) AS questions,COALESCE(SUM(is_correct),0) AS correct FROM $t WHERE user_id=%d",$uid),ARRAY_A);foreach($a as &$v)$v=(int)$v;unset($v);$a['incorrect']=$a['attempts']-$a['correct'];$a['accuracy']=$a['attempts']?round(100*$a['correct']/$a['attempts'],1):null;$a['by_source']=$wpdb->get_results($wpdb->prepare("SELECT m.source_type,m.mtp_series,COUNT(*) AS attempts,SUM(at.is_correct) AS correct FROM $t at JOIN $q m ON m.id=at.mcq_id WHERE at.user_id=%d GROUP BY m.source_type,m.mtp_series",$uid),ARRAY_A);$a['topic_mistakes']=$wpdb->get_results($wpdb->prepare("SELECT t.label,COUNT(*) AS mistakes FROM $t at JOIN ".CAFCC_MCQ::table('tags')." t ON t.mcq_id=at.mcq_id AND t.kind='standard' WHERE at.user_id=%d AND at.is_correct=0 GROUP BY t.label ORDER BY mistakes DESC LIMIT 12",$uid),ARRAY_A);$a['recent']=$wpdb->get_results($wpdb->prepare("SELECT at.attempt_number,at.is_correct,at.active_seconds,at.created_at,m.id,m.stable_id,m.source_type,m.mtp_series,m.exam_attempt,m.question_number FROM $t at JOIN $q m ON m.id=at.mcq_id WHERE at.user_id=%d ORDER BY at.id DESC LIMIT 10",$uid),ARRAY_A);return $a;}
    public static function test_create($v){if(is_wp_error($e=CAFCC_Library::allowed()))return $e;if(!is_array($v)||array_diff(array_keys($v),array('filter','count','minutes','request_key'))||!preg_match('/^[a-f0-9-]{36}$/D',$v['request_key']??'')||!is_int($v['count']??null)||$v['count']<1||$v['count']>30||!is_int($v['minutes']??null)||$v['minutes']<1||$v['minutes']>180)return CAFCC_Repository::error('Choose 1–30 questions and 1–180 practice minutes.');$f=self::filters($v['filter']??array());if(is_wp_error($f))return $f;return CAFCC_Academic::transaction(function()use($v,$f){global $wpdb;$uid=get_current_user_id();$t=CAFCC_MCQ::table('tests');$old=$wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE request_key=%s AND user_id=%d FOR UPDATE",$v['request_key'],$uid),ARRAY_A);if($old)return self::test_view($old);[$from,$w,$a]=self::parts($f);$sql="SELECT m.id,m.revision $from WHERE $w ORDER BY m.id LIMIT ".$v['count'];$rows=$wpdb->get_results($a?$wpdb->prepare($sql,$a):$sql,ARRAY_A);if(!$rows)return CAFCC_Repository::error('No eligible MCQs match these filters.');$r=array('test_key'=>wp_generate_uuid4(),'request_key'=>$v['request_key'],'user_id'=>$uid,'started_at'=>current_time('mysql',true),'ends_at'=>gmdate('Y-m-d H:i:s',time()+$v['minutes']*60),'payload'=>wp_json_encode(array('items'=>$rows,'choices'=>array(),'seconds'=>array(),'current_id'=>0,'last_entered'=>time(),'filter'=>$f,'scoring'=>'Practice only: 1 point for a correct response; 0 otherwise. No claim of official ICAI marking.')),'result'=>'{}');if(false===$wpdb->insert($t,$r))return CAFCC_Repository::error('Cannot retain timed test.',500);$r['id']=$wpdb->insert_id;$r['status']='open';return self::test_view($r);});}
    public static function test_get($key,$lock=false){global $wpdb;if(!is_string($key)||!preg_match('/^[a-f0-9-]{36}$/D',$key))return CAFCC_Repository::error('Invalid private test.');$r=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.CAFCC_MCQ::table('tests').' WHERE test_key=%s AND user_id=%d'.($lock?' FOR UPDATE':''),$key,get_current_user_id()),ARRAY_A);return $r?:CAFCC_Repository::error('Private test not found.',404);}
    public static function test_view($r){if(is_wp_error($e=CAFCC_Library::allowed()))return $e;$d=json_decode($r['payload'],true);$out=array('test_key'=>$r['test_key'],'status'=>$r['status'],'started_at'=>$r['started_at'],'ends_at'=>$r['ends_at'],'server_time'=>current_time('mysql',true),'items'=>$d['items'],'choices'=>$d['choices'],'scoring'=>$d['scoring']);if($r['status']==='submitted'){$result=json_decode($r['result'],true);foreach($result['items'] as &$item){$q=self::open($item['mcq_id']);if(is_wp_error($q)||(int)$q['revision']!==(int)$item['revision']){unset($item['correct_options'],$item['explanation_html']);$item['unavailable']='Content withdrawn or revised since this test.';}}unset($item);$out['result']=$result;}return $out;}
    public static function test_step($key,$v){if(is_wp_error($e=CAFCC_Library::allowed()))return $e;if(!is_array($v)||array_diff(array_keys($v),array('action','mcq_id','selected'))||!in_array($v['action']??'',array('save','submit','view'),true))return CAFCC_Repository::error('Choose Save or Submit Test.');return CAFCC_Academic::transaction(function()use($key,$v){global $wpdb;$r=self::test_get($key,true);if(is_wp_error($r))return $r;if($r['status']==='submitted')return self::test_view($r);$d=json_decode($r['payload'],true);$expired=time()>=strtotime($r['ends_at'].' UTC');$now=min(time(),strtotime($r['ends_at'].' UTC'));$prior=(int)($d['current_id']??0);if($prior)$d['seconds'][(string)$prior]=($d['seconds'][(string)$prior]??0)+max(0,$now-(int)($d['last_entered']??$now));$d['last_entered']=$now;if(in_array($v['action'],array('save','view'),true)){$id=(int)($v['mcq_id']??0);$item=null;foreach($d['items'] as $it)if((int)$it['id']===$id)$item=$it;if(!$item)return CAFCC_Repository::error('This question is not part of your test.');if($expired)return CAFCC_Repository::error('Time has elapsed. Submit your previously saved responses.',409);$q=self::open($id);if(is_wp_error($q))return $q;if((int)$q['revision']!==(int)$item['revision'])return CAFCC_Repository::error('Question revision changed. It will not be scored against a different key.',409);if($v['action']==='save'){$choice=self::choice($q,$v['selected']??null);if(is_wp_error($choice))return $choice;$d['choices'][(string)$id]=$choice;}$d['current_id']=$id;if(false===$wpdb->update(CAFCC_MCQ::table('tests'),array('payload'=>wp_json_encode($d)),array('id'=>$r['id'])))return CAFCC_Repository::error('Cannot save test response.',500);$r['payload']=wp_json_encode($d);return self::test_view($r);}
            $result=array('questions'=>count($d['items']),'answered'=>0,'correct'=>0,'incorrect'=>0,'unanswered'=>0,'unscored'=>0,'items'=>array(),'scoring'=>$d['scoring']);foreach($d['items'] as $item){$id=(int)$item['id'];$entry=array('mcq_id'=>$id,'revision'=>(int)$item['revision']);$selected=$d['choices'][(string)$id]??array();$q=self::open($id);if(is_wp_error($q)||(int)$q['revision']!==(int)$item['revision']){$result['unscored']++;$entry['unavailable']='Withdrawn or revised; excluded from scoring.';}elseif(!$selected){$result['unanswered']++;$entry['selected']=array();$entry['correct_options']=$q['correct'];}else{$a=self::record($q,$selected,(int)($d['seconds'][(string)$id]??0),$r['id']);if(is_wp_error($a))return $a;$feedback=self::feedback($q,$a);$entry=array_merge($entry,$feedback);$result['answered']++;$result[$a['is_correct']?'correct':'incorrect']++;}$result['items'][]=$entry;}$result['score']=$result['correct'];$result['scored_question_count']=$result['questions']-$result['unscored'];$result['duration_seconds']=max(0,min(time(),strtotime($r['ends_at'].' UTC'))-strtotime($r['started_at'].' UTC'));$result['per_question_time_note']='Per-question elapsed view time is measured server-side between explicit question transitions; it does not certify attention or mastery.';if(false===$wpdb->update(CAFCC_MCQ::table('tests'),array('status'=>'submitted','submitted_at'=>current_time('mysql',true),'payload'=>wp_json_encode($d),'result'=>wp_json_encode($result)),array('id'=>$r['id'])))return CAFCC_Repository::error('Cannot retain test results.',500);$r['status']='submitted';$r['result']=wp_json_encode($result);return self::test_view($r);
        });}
    public static function screen(){wp_enqueue_style('cafcc-mcq',plugins_url('assets/mcq.css',CAFCC_FILE),array('cafcc-v2'),CAFCC_VERSION);wp_enqueue_script('cafcc-mcq',plugins_url('assets/mcq.js',CAFCC_FILE),array(),CAFCC_VERSION,true);wp_localize_script('cafcc-mcq','CAFCCMCQ',array('url'=>rest_url('cafcc/v9/mcq/'),'nonce'=>wp_create_nonce('wp_rest')));return '<section class="cc-mcq" data-mcq><header><span class="cc-eyebrow">YOUR MCQ PRACTICE</span><h1>Choose. Check. Learn.</h1><p>Objective practice stays separate from subjective self-assessment.</p></header><form class="cc-mcq-filters"><label>Subject<select name="subject"><option value="">All subjects</option><option value="FR">Financial Reporting</option><option value="AUDIT">Advanced Auditing</option><option value="AFM">Advanced Financial Management</option><option value="DT">Direct Tax</option><option value="IDT">Indirect Tax</option><option value="IBS">IBS</option></select></label><label>Attempt<select name="attempt"><option value="">All attempts</option></select></label><label>Source<select name="source_series"><option value="">All sources</option><option value="rtp">RTP</option><option value="mtp:I">MTP I</option><option value="mtp:II">MTP II</option><option value="exam">Examination</option></select></label><label>Topic / Standard<input name="standard_search" type="search" placeholder="Ind AS 115 or Revenue"><select name="standard"><option value="">All available standards</option></select></label><label>Concept<select name="concept"><option value="">All matching concepts</option></select></label><label>Practice list<select name="mode"><option value="all">All eligible</option><option value="unattempted">Unattempted</option><option value="incorrect">Latest response incorrect</option><option value="bookmarked">Bookmarked</option><option value="attempted">Previously attempted</option></select></label><button type="reset">Clear All</button></form><div class="cc-mcq-chips" aria-live="polite"></div><div class="cc-mcq-actions"><button type="button" data-mcq-test>Timed practice test</button><button type="button" data-mcq-resume hidden>Resume saved test</button></div><p data-mcq-status role="status"></p><div data-mcq-test-panel hidden></div><div data-mcq-list></div><nav data-mcq-pagination aria-label="MCQ pages"></nav><article data-mcq-reader hidden></article><section data-mcq-metrics></section></section>';}
    public static function init(){add_action('rest_api_init',function(){$p=function($r){return CAFCC_REST::permission($r);};$routes=array('activity'=>array('GET',function($r){return self::activity($r->get_params());}),'questions'=>array('GET',function($r){return self::list($r->get_params());}),'facets'=>array('GET',function($r){return self::facets($r->get_params());}),'metrics'=>array('GET',function(){return is_wp_error($e=CAFCC_Library::allowed())?$e:self::metrics();}),'question/(?P<id>[1-9][0-9]*)'=>array('GET',function($r){return self::question((int)$r['id']);}),'question/(?P<id>[1-9][0-9]*)/begin'=>array('POST',function($r){return self::begin((int)$r['id']);}),'question/(?P<id>[1-9][0-9]*)/check'=>array('POST',function($r){$v=CAFCC_Studio::body($r,5000);return is_wp_error($v)?$v:self::check((int)$r['id'],$v);}),'question/(?P<id>[1-9][0-9]*)/personal'=>array('POST',function($r){$v=CAFCC_Studio::body($r,5000);return is_wp_error($v)?$v:self::personal((int)$r['id'],$v);}),'tests'=>array('POST',function($r){$v=CAFCC_Studio::body($r,5000);return is_wp_error($v)?$v:self::test_create($v);}));foreach($routes as $route=>$x)register_rest_route('cafcc/v9','/mcq/'.$route,array('methods'=>$x[0],'permission_callback'=>$p,'callback'=>$x[1]));register_rest_route('cafcc/v9','/mcq/tests/(?P<key>[a-f0-9-]{36})',array(array('methods'=>'GET','permission_callback'=>$p,'callback'=>function($r){if(is_wp_error($e=CAFCC_Library::allowed()))return $e;$x=self::test_get($r['key']);return is_wp_error($x)?$x:self::test_view($x);}),array('methods'=>'POST','permission_callback'=>$p,'callback'=>function($r){$v=CAFCC_Studio::body($r,5000);return is_wp_error($v)?$v:self::test_step($r['key'],$v);})));});add_filter('rest_post_dispatch',function($response,$server,$r){if(str_starts_with($r->get_route(),'/cafcc/v9/')){$response->header('Cache-Control','private, no-store');$response->header('Vary','Cookie');}return $response;},10,3);}
